package disaster.resource;
import disaster.exceptions.InsufficientResourceException;
public abstract class Resource { private static int nextId=1; private final String resourceId; private final String name,unit; private long quantity; private final long originalQuantity;
 protected Resource(String name,long quantity,String unit){if(quantity<0)throw new IllegalArgumentException("Negative resource quantity");this.resourceId="RES-"+nextId++;this.name=name;this.quantity=quantity;this.originalQuantity=quantity;this.unit=unit;}
 public synchronized void addResource(long value){if(value<0)throw new IllegalArgumentException("Negative addition");quantity+=value;} public synchronized void removeResource(long value)throws InsufficientResourceException{if(value<0)throw new IllegalArgumentException("Negative removal");if(quantity<value)throw new InsufficientResourceException(name+" insufficient");quantity-=value;} public synchronized long drain(long requested){long allocated=Math.min(quantity,requested);quantity-=allocated;return allocated;} public synchronized long getQuantity(){return quantity;} public long getOriginalQuantity(){return originalQuantity;} public String getName(){return name;} public String getUnit(){return unit;} public String getResourceId(){return resourceId;} }
